/**
 * ResearchReportPanel.test.tsx
 * ============================
 * Renders the point-wise research report against the REAL API response that
 * the backend produced (see `src/test-fixtures/realVerificationResponses.json`,
 * generated by `scratch/build_frontend_fixture.py` from a live run).
 *
 * These assertions prove that the panel displays the backend's actual values
 * and that it does not invent content when a stage produced nothing.
 */
import { describe, it, expect } from 'vitest';
import { render, screen, fireEvent } from '@testing-library/react';
import ResearchReportPanel from './ResearchReportPanel';
import { UnifiedVerificationResponse } from '../types';
import fixture from '../test-fixtures/realVerificationResponses.json';

const responses = fixture as unknown as Record<string, UnifiedVerificationResponse>;

describe('ResearchReportPanel - real API responses', () => {
  it('renders the point-wise report header', () => {
    render(<ResearchReportPanel result={responses.text} />);
    expect(screen.getByText(/Point-Wise Research Report/i)).toBeTruthy();
  });

  it('renders the real input claim from the text response', () => {
    render(<ResearchReportPanel result={responses.text} />);
    const claim =
      responses.text.research_report!.executive_summary.input_claim!;
    expect(claim).toBeTruthy();
    const matcher = new RegExp(
      claim.slice(0, 40).replace(/[.*+?^${}()|[\]\\]/g, '\\$&'),
      'i'
    );
    expect(screen.getAllByText(matcher).length).toBeGreaterThan(0);
  });

  it('renders the real verdict and the confidence basis', () => {
    render(<ResearchReportPanel result={responses.text} />);
    const summary = responses.text.research_report!.executive_summary;
    // The verdict rendered must be the verdict the backend returned.
    expect(summary.verdict).toBeTruthy();
    expect(screen.getByText(summary.verdict as string)).toBeTruthy();
    // The panel must label what the number actually measures.
    const label = summary.confidence_basis === 'verification_coverage'
      ? /Evidence coverage/i
      : /Confidence/i;
    expect(screen.getAllByText(label).length).toBeGreaterThan(0);
  });

  it('states that an UNVERIFIED verdict is not a refutation', () => {
    const { container } = render(<ResearchReportPanel result={responses.audio} />);
    const summary = responses.audio.research_report!.executive_summary;
    expect(summary.verdict).toBe('UNVERIFIED');
    expect(summary.confidence_basis).toBe('verification_coverage');
    expect(container.textContent).toMatch(/not a probability that the claim is true or false/i);
    expect(container.textContent).toMatch(/did not settle the claim/i);
  });

  it('renders the real search queries the backend issued', () => {
    render(<ResearchReportPanel result={responses.text} />);
    const queries = responses.text.research_report!.methodology.search_queries;
    expect(queries.length).toBeGreaterThan(0);
    for (const q of queries) {
      const matcher = new RegExp(
        q.query.replace(/[.*+?^${}()|[\]\\]/g, '\\$&').slice(0, 30),
        'i'
      );
      expect(screen.getAllByText(matcher).length).toBeGreaterThan(0);
    }
  });

  it('renders the real methodology counts', () => {
    render(<ResearchReportPanel result={responses.text} />);
    const method = responses.text.research_report!.methodology;
    expect(method.sources_retrieved).toBeGreaterThan(0);
    expect(method.articles_scraped).toBeGreaterThan(0);
    expect(screen.getByText(/Search queries issued \(/)).toBeTruthy();
    expect(screen.getByText(/candidate URL\(s\) retrieved/i)).toBeTruthy();
  });

  it('reports the real evidence-policy counters', () => {
    const { container } = render(<ResearchReportPanel result={responses.text} />);
    const method = responses.text.research_report!.methodology;
    // The independence stage must appear with its real counters.
    expect(container.textContent).toMatch(/independent publisher group\(s\)/);
    expect(container.textContent).toMatch(/primary supporting group\(s\)/);
    expect(method.sources_retrieved).toBeGreaterThan(0);
  });

  it('renders the agent narrative and the critic review verbatim', () => {
    render(<ResearchReportPanel result={responses.text} />);
    const summary = responses.text.research_report!.executive_summary;
    expect(summary.agent_narrative).toBeTruthy();
    expect(summary.critic_review).toBeTruthy();
    expect(screen.getAllByText(/Verification agent/i).length).toBeGreaterThan(0);
    expect(screen.getAllByText(/Critic agent/i).length).toBeGreaterThan(0);
  });

  it('renders the real limitations', () => {
    render(<ResearchReportPanel result={responses.text} />);
    const limits = responses.text.research_report!.executive_summary.limitations;
    expect(limits.length).toBeGreaterThan(0);
    expect(screen.getByText(/Uncertainties & limitations/i)).toBeTruthy();
  });

  it('renders the contextual findings with their real source links', () => {
    const { container } = render(<ResearchReportPanel result={responses.text} />);
    const contextual = responses.text.research_report!.findings.contextual || [];
    expect(contextual.length).toBeGreaterThan(0);

    // The finding cards are expandable: open the first contextual card so its
    // excerpt, reliability details and clickable source link are rendered.
    const firstTitle = contextual[0].title;
    const titleNode = Array.from(container.querySelectorAll('p')).find((p) =>
      (p.textContent || '').trim().startsWith(firstTitle.slice(0, 25))
    );
    expect(titleNode).toBeTruthy();
    fireEvent.click(titleNode!.parentElement!.parentElement!);

    const links = Array.from(container.querySelectorAll('a[href]')) as HTMLAnchorElement[];
    const realUrls = contextual
      .map((f) => f.source_url)
      .filter((u): u is string => Boolean(u));
    expect(realUrls.length).toBeGreaterThan(0);
    for (const url of realUrls.slice(0, 1)) {
      expect(links.some((a) => a.getAttribute('href') === url)).toBe(true);
    }
  });

  it('never links a URL that the backend did not supply', () => {
    const { container } = render(<ResearchReportPanel result={responses.text} />);
    const links = Array.from(container.querySelectorAll('a[href]')) as HTMLAnchorElement[];
    for (const a of links) {
      const href = a.getAttribute('href') || '';
      expect(href.startsWith('http://') || href.startsWith('https://')).toBe(true);
    }
  });

  it('reports that research was skipped for the image response, with the reason', () => {
    render(<ResearchReportPanel result={responses.image} />);
    const method = responses.image.research_report!.methodology;
    expect(method.research_skipped).toBe(true);
    expect(screen.getByText(/Research was skipped/i)).toBeTruthy();
    expect(screen.getAllByText(/No verifiable claim was extracted/i).length).toBeGreaterThan(0);
  });

  it('renders no findings for a skipped-research response', () => {
    const { container } = render(<ResearchReportPanel result={responses.video} />);
    const report = responses.video.research_report!;
    for (const bucket of Object.values(report.findings)) {
      expect((bucket || []).length).toBe(0);
    }
    // The panel must not have produced a findings list of its own.
    expect(container.textContent).not.toMatch(/Supporting finding #1/);
  });

  it('records the evidence gap for the video response', () => {
    render(<ResearchReportPanel result={responses.video} />);
    const gaps = responses.video.research_report!.evidence_gaps;
    expect(gaps.length).toBeGreaterThan(0);
    expect(screen.getByText(/Unresolved Questions & Evidence Gaps/i)).toBeTruthy();
  });

  it('renders the audio response with its real transcription-derived claim', () => {
    render(<ResearchReportPanel result={responses.audio} />);
    const summary = responses.audio.research_report!.executive_summary;
    expect(summary.input_claim).toBeTruthy();
    expect(screen.getByText(/Input under investigation/i)).toBeTruthy();
  });

  it('shows an honest message when the API returned no report', () => {
    const withoutReport = { ...responses.text, research_report: null } as UnifiedVerificationResponse;
    render(<ResearchReportPanel result={withoutReport} />);
    expect(screen.getByText(/No research report was returned/i)).toBeTruthy();
  });

  // ---------------------------------------------------------------------
  // Deterministic-gate policy accounting
  // ---------------------------------------------------------------------

  it('reports that the evidence policy data was valid', () => {
    render(<ResearchReportPanel result={responses.text} />);
    const diagnostics = responses.text.research_report!.executive_summary
      .policy_diagnostics;
    expect(diagnostics).toBeTruthy();
    if (diagnostics!.verdict_restricted) {
      expect(screen.getByText(/POLICY DATA INVALID/i)).toBeTruthy();
    } else {
      expect(screen.getByText(/POLICY DATA VALID|GATE NOT RUN/i)).toBeTruthy();
    }
  });

  it('shows the unusable policy fields and the internal-issue explanation', () => {
    const base = responses.text;
    const broken: UnifiedVerificationResponse = {
      ...base,
      research_report: {
        ...base.research_report!,
        executive_summary: {
          ...base.research_report!.executive_summary,
          policy_diagnostics: {
            gate_ran: true,
            policy_data_valid: false,
            policy_data_errors: ["missing 'primary_correction_groups'"],
            verdict_restricted: true,
            explanation:
              'The evidence policy data was incomplete or invalid, so the deterministic ' +
              'gate could not evaluate the evidence policy and restricted the result to ' +
              'UNVERIFIED. Unusable policy field(s): missing ' +
              "'primary_correction_groups'. This is an internal evidence-accounting issue, " +
              'NOT proof that the claim is false, and it does not mean the claim was refuted.',
          },
        },
      },
    };

    const { container } = render(<ResearchReportPanel result={broken} />);

    expect(screen.getByText(/POLICY DATA INVALID/i)).toBeTruthy();
    // The field name appears both in the explanation and in the error list.
    expect(
      screen.getAllByText(/missing 'primary_correction_groups'/i).length
    ).toBeGreaterThan(0);
    expect(container.textContent).toMatch(/NOT proof that the claim is false/i);
    expect(container.textContent).toMatch(/restricted the result to UNVERIFIED/i);
  });

  it('does not claim the policy was checked when the gate never ran', () => {
    const base = responses.text;
    const noGate: UnifiedVerificationResponse = {
      ...base,
      research_report: {
        ...base.research_report!,
        executive_summary: {
          ...base.research_report!.executive_summary,
          policy_diagnostics: {
            gate_ran: false,
            policy_data_valid: null,
            policy_data_errors: [],
            verdict_restricted: false,
            explanation:
              'The deterministic evidence gate did not run for this result, so no ' +
              'evidence policy counters were evaluated.',
          },
        },
      },
    };

    render(<ResearchReportPanel result={noGate} />);
    expect(screen.getByText(/GATE NOT RUN/i)).toBeTruthy();
    expect(screen.queryByText(/POLICY DATA VALID/i)).toBeNull();
  });
});
